function feNe(){const n=(typeof scene!=='undefined'&&scene&&scene.ne)||{},ren=o=>{const u={};Object.keys(o||{}).sort().forEach(k=>{const v=o[k];if(v&&typeof v==='object'){const w={};Object.keys(v).sort().forEach(q=>{if(v[q]!==undefined&&v[q]!==false&&v[q]!==null)w[q]=v[q]});if(Object.keys(w).length)u[k]=w}else if(v!==undefined&&v!==null&&v!==0)u[k]=v});return u};return{trim:ren(n.trim),grp:ren(n.grp),ltFra:ren(n.ltFra),eff:ren(n.eff)/* v9.107 */,pos:gitPosSnap(n.pos),git:n.git?[n.git.model||'C',+n.git.lod||100,+n.git.vand||100,n.git.del?1:0,n.git.ramme?[n.git.ramme.cx,n.git.ramme.cy,n.git.ramme.w,n.git.ramme.h]:0]:0}}/* v9.105: pladser og gitter *//* v9.84: lydtræk slået fra */
