function tilpasThr(m,i,v){const k=m.band;if(!BANDS.some(b=>b[0]===k)||TIL_SLAG.includes(k))return m;const nu=performance.now(),x=Number.isFinite(+v)?+v:0;let mu=TIL.mu[k];if(mu===undefined){mu=x;TIL.sidst[k]=nu}
 const d=Math.min(.1,Math.max(0,(nu-(TIL.sidst[k]||nu))/1000));let dv=TIL.dev[k]===undefined?.1:TIL.dev[k];if(d>0){const a=1-Math.exp(-d/Math.max(.5,+set.tilpasTid||3));dv+=(Math.abs(x-mu)-dv)*a;mu+=(x-mu)*a;TIL.sidst[k]=nu}TIL.mu[k]=mu;TIL.dev[k]=dv;
 /* tærsklen = gennemsnit + c × typisk udsving (som i professionel slag-detektion); c = 1,2 ved din tærskel 0,3, højere tærskel giver højere c (mindre følsom) */const c=Math.max(.4,1.2+((+m.thr||0)-.3)*4),thr=Math.max(+(set.tilpasBund??.05),Math.min(.95,mu+c*Math.max(.03,dv)));TIL.eff[i]=thr;return{...m,thr}}
