/* ========== v6.9 / v7.1: MESH 3D (Radial Mesh i rigtig 3D med shaders) ==========
   Bygget med Three.js r128 (MIT, indlejret i filen). To former: FLAD (standard) er en kopi af Radial Mesh: lyden i en ydre ring, effekter og figurer i en indre ring og buede baner imellem, men i rigtig 3D, så banerne bøjer ud mod kameraet, og man kan dreje og se dybden. KUGLE lægger lyden på en ydre kugleskal og effekterne på en indre.
   Shaders: kuglerne har en glødende kant (fresnel), der lyser kraftigere, når de pulserer; energien strømmer synligt langs lysbanerne, hurtigere jo mere de slår ud; baggrunden er en levende tåge, der skifter farve og lysstyrke med musikken.
   Puls som i Radial Mesh: en kugle blinker op, når dens lyd slår ud, og en bane blinker og skyder en lys partikel af sted, når dens forbindelse slår ud. Desuden baneringe, et trådnet om kernen, stjernestøv og chokbølger på kraftige slag.
   Mus: træk = drej, hjul = zoom, dobbeltklik = nulstil. Stå alene: knapperne skjules, og kameraet bevæger sig af sig selv. m3Data() giver data i samme form, som blev beskrevet til Lydkosmos-chatten. */
const M3_LYS0={bloom:.05,bloomR:.05,bloomT:.11,film:true,eks:1,vig:.3,korn:.03,spor:.5,pump:true,pumpFart:1,pumpStr:1,pumpN:7,pumpTaet:.06,dans:false,dansKilde:'auto',dansStr:1,dansLys:.5,dansDyb:30,dansX:0,dansY:0,kugle:.3,glorie:.45,vaekst:.9,kant:.9,kerneStr:.6,kerneLys:.5,ico:false,ringe:true,dioder:false,dBane:18,dRing:48,dStr:3,bane:1.4,flow:0,partStr:1.5,partN:6,puls:true,hue:0,maet:0,taage:0,stoev:true,afstand:46,svaj:1,fart:1,skarp:1.5};/* v7.3: brugerens egne værdier er standard */
function m3L(){return Object.assign({},M3_LYS0,(typeof scene!=='undefined'&&scene&&scene.m3)||{})}
const M3={r:null,sc:null,cam:null,rod:null,sig:'',noder:{},links:[],kerne:null,az:Math.PI/2,el:0,dist:30,auto:true,lbl:true,part:true,alene:false,sidstT:0,traek:null,glod:null,udSize:null,form:'flad',frit:false,tTot:0};
