 const maal=mid.map(id=>{let mx=0;maps.forEach((m,i)=>{if(m.effect===id)mx=Math.max(mx,+(env[i]||0))});let n=id;try{n=effName(id)}catch(e){}return{id,navn:n,v:Math.max(0,Math.min(1,mx))}});
 const forbindelser=maps.map((m,i)=>({fra:m.band,til:m.effect,v:Math.max(0,Math.min(1,+(env[i]||0))),gain:m.gain,thr:m.thr,af:!!m.off}));
