function m3Tekst(t,farve){const c=document.createElement('canvas'),g=c.getContext('2d');g.font='bold 96px system-ui,sans-serif';const w=Math.ceil(g.measureText(t).width)+48;c.width=w;c.height=136;g.font='bold 96px system-ui,sans-serif';g.fillStyle='rgba(5,8,20,.55)';g.fillRect(0,12,w,112);g.fillStyle=farve;g.textBaseline='middle';g.fillText(t,24,70);const tx=new THREE.CanvasTexture(c);tx.minFilter=THREE.LinearMipmapLinearFilter;tx.anisotropy=4;const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tx,transparent:true,depthWrite:false}));sp.scale.set(w/136*.5,.5,1);return sp}/* v7.3: skarpere navne */
function m3GlodTex(){const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d'),gr=g.createRadialGradient(128,128,0,128,128,128);gr.addColorStop(0,'rgba(255,255,255,1)');gr.addColorStop(.25,'rgba(255,255,255,.55)');gr.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=gr;g.fillRect(0,0,256,256);return new THREE.CanvasTexture(c)}
function m3Fib(n,R,i){const y=n>1?1-(i/(n-1))*2:0,rr=Math.sqrt(Math.max(0,1-y*y)),th=i*2.399963;return new THREE.Vector3(Math.cos(th)*rr*R,y*R*.75,Math.sin(th)*rr*R)}
