const FG={lyd:{host:'w25',navn:'Arbejdsfelt',faner:[['w33','Node-editor'],['w1','Tidslinje'],['w7','Analyse'],['w31','Lydkilde']]},vaerk:{host:'w26',navn:'Værksted',faner:[['w18','Lydtræk-guide'],['w19','Audit'],['w20','Detektion']]},ops:{host:'w27',navn:'Opsætninger',faner:[['w13','Opsætninger'],['w21','Preset (tekst)']]}};
(function(){const d=set.fg&&typeof set.fg==='object'?set.fg:{};set.fg={};Object.keys(FG).forEach(g=>{const x=d[g]||{};set.fg[g]={aktiv:FG[g].faner.some(f=>f[0]===x.aktiv)?x.aktiv:FG[g].faner[0][0],ude:Array.isArray(x.ude)?x.ude.filter(i=>FG[g].faner.some(f=>f[0]===i)):[]}})})();
const fgAf=id=>Object.keys(FG).find(g=>FG[g].faner.some(f=>f[0]===id))||null;
const fgIGruppe=id=>{const w=$(id);return !!(w&&w.classList.contains('fg-member'))};
