function fgInd(g,id){const w=$(id),k=document.querySelector('.fg-krop[data-fg="'+g+'"]');if(!w||!k||fgIGruppe(id))return;if(w.classList.contains('min'))miniSaet(w,false);if(w.classList.contains('max')){w.classList.remove('max');const mx=w.querySelector('.mx');if(mx)mx.textContent='Maksimér'}w.dataset.fgStil=w.getAttribute('style')||'';w.classList.add('fg-member');w.hidden=false;k.appendChild(w);set.fg[g].ude=set.fg[g].ude.filter(x=>x!==id)}
function fgVisHost(g){const h=$(FG[g].host);if(!h)return;h.hidden=false;if(h.classList.contains('min'))miniSaet(h,false);try{aktivSaet(h)}catch(e){}}
function fgVaelg(g,id,stille){if(!fgIGruppe(id))return;set.fg[g].aktiv=id;scGem();FG[g].faner.forEach(([fid])=>{const w=$(fid);if(!fgIGruppe(fid))return;w.classList.toggle('fg-aktiv',fid===id);w.hidden=false});requestAnimationFrame(()=>{try{window.dispatchEvent(new Event('resize'))}catch(e){}});fgFaner(g);if(!stille)msg(FG[g].navn+' viser nu '+fgNavn(id)+'.')}
function fgRiv(g,id,stille){const w=$(id);if(!fgIGruppe(id))return;const h=$(FG[g].host),ws=$('ws');w.classList.remove('fg-member','fg-aktiv');ws.appendChild(w);const r=h.getBoundingClientRect(),wr=ws.getBoundingClientRect();
 w.setAttribute('style','left:'+Math.round(r.left-wr.left+40)+'px;top:'+Math.round(r.top-wr.top+60)+'px;width:'+Math.round(Math.max(420,r.width*.8))+'px;height:'+Math.round(Math.max(360,r.height*.8))+'px');w.style.zIndex=++zTop;w.hidden=false;
 if(!set.fg[g].ude.includes(id))set.fg[g].ude.push(id);const n=FG[g].faner.find(f=>fgIGruppe(f[0])&&!$(f[0]).classList.contains('niv-skjult'));if(set.fg[g].aktiv===id&&n)fgVaelg(g,n[0],true);scGem();fgFaner(g);try{dockOpdat()}catch(e){}if(!stille)msg(fgNavn(id)+' er nu sit eget vindue. Tryk ⤵ Til samlingen i dets overskrift for at lægge det tilbage.')}
function fgTilbage(g,id){fgInd(g,id);scGem();fgVaelg(g,id,true);fgVisHost(g);try{dockOpdat()}catch(e){}msg(fgNavn(id)+' er lagt tilbage i '+FG[g].navn+'.')}
function fgFaner(g){const el=document.querySelector('.fg-faner[data-fg="'+g+'"]');if(!el)return;const a=set.fg[g].aktiv;el.innerHTML=FG[g].faner.filter(([id])=>fgIGruppe(id)&&!$(id).classList.contains('niv-skjult')).map(([id,n])=>'<button class="ghost sc-f'+(id===a?' on':'')+'" role="tab" aria-selected="'+(id===a)+'" data-fgv="'+id+'">'+n+'</button>').join('')+'<span class="sc-luft"></span><button class="ghost" data-fgriv title="Gør den valgte fane til sit eget vindue.">⇱ Riv løs</button>'}
