/* ========== v8.3: ARBEJDSFLADE, TOPBAR-LAYOUTS OG OPRYDNING ==========
   Arbejdsfladen (#ws) ligger fast mellem topbaren, sidebjælken og bundbjælken og ruller for sig selv, så vinduer aldrig kan glide ind under eller over bjælkerne.
   Topbaren har fem store layout-knapper: Overblik (Scene og Editor store, Mapping, Lyd og Generator under, resten som små fliser), Show (Scene fylder fladen), Byg (Scene med Radial Mesh, Mapping og Editor), Lyd (Scene med EQ+, Lyd, Generator og Mapping) og Figurer (Scene og Editor side om side). Alle vinduer, der ikke er med i layoutet, lægges som små fliser pænt under det synlige. Mine ▾ henter dine egne gemte layouts (pladserne 1 til 6), og 💾 Gem gemmer det, du har nu. De gamle faste layouts er fjernet. */
const LAY3=[['ao-sang','1 · Analyse','Arbejdsområdet Analyse: lydkilde, bølgeform, spektrum, niveau, taktslag, spor og den avancerede analyse (tasten 1)'],['ao-scene','2 · Scene','Arbejdsområdet Scene: Live preview, Mesh 3D, Øjet og Radial Mesh, Figurer og Egenskaber (tasten 2)'],['ao-regler','3 · Regler','Arbejdsområdet Regler: Node-editoren med Noder og Matrix, og en lille Live preview (tasten 3)'],['ao-show','4 · Show','Arbejdsområdet Show: scenen stor, Opsætninger og Show (tasten 4)'],['overblik','Overblik','Scene og Editor store, de vigtigste vinduer under, resten som små fliser'],['show','Show','Scene over hele fladen, klar til at spille'],['byg','Byg','Radial Mesh, Mapping og Editor: byg forbindelser'],['lyd','Lyd','EQ+, tidslinje, generator og Mapping: arbejd med lyden'],['figurer','Figurer','Live preview og Editor side om side'],['noder','Noder','Node-editoren stor i hele bredden, Scenen smal ovenover']];
const LAY3_PLAN={
 overblik:[['w23',0,0,.6,.64,'w2'],['w6',.6,0,.4,.64],['w25',0,.64,.67,.36],['w4',.67,.64,.33,.36]],
 show:[['w23',0,0,1,1,'w2']],
 byg:[['w23',0,0,.6,1,'w5'],['w6',.6,0,.4,1]],
 lyd:[['w23',0,0,.6,.62,'w24'],['w25',.6,0,.4,.62],['w4',0,.62,1,.38]],
 figurer:[['w23',0,0,.55,1,'w2'],['w6',.55,0,.45,1]],
 noder:[['w23',0,0,1,.3,'w2'],['w25',0,.3,1,.7]]};
function lay3Frie(){return [...document.querySelectorAll('#ws > .win')].filter(w=>!w.classList.contains('niv-skjult'))}
function lay3Anvend(k,stille){const plan=LAY3_PLAN[k];if(!plan)return;const ws=$('ws'),G=8,W=ws.clientWidth*(set.bredt?2:1)-G,H=ws.clientHeight-G,brugt=new Set();
 const saet=(w,x,y,b,h)=>{if(w.classList.contains('max')){w.classList.remove('max');const mx=w.querySelector('.mx');if(mx)mx.textContent='Maksimér'}if(w.classList.contains('min'))try{miniSaet(w,false)}catch(e){}w.hidden=false;w.style.left=Math.round(G+x)+'px';w.style.top=Math.round(G+y)+'px';w.style.width=Math.round(b-G)+'px';w.style.height=Math.round(h-G)+'px';delete w.dataset.snap};
 plan.forEach(([id,x,y,b,h,fane])=>{const w=$(id);if(!w||w.classList.contains('niv-skjult'))return;if(w.parentNode!==ws)return;saet(w,x*W,y*H,b*W,h*H);brugt.add(id);if(fane&&id==='w23'){try{const fw=$(fane);if(fw&&!fw.classList.contains('scene-member'))scIndIScene(fane);scVaelg(fane,true)}catch(e){}}});
 /* resten som små fliser under det synlige */const rest=lay3Frie().filter(w=>!brugt.has(w.id)&&!(w.hidden&&!['w4','w6','w23','w25','w26','w27'].includes(w.id)));const kol=W>1500?4:3,fb=W/kol,fh=Math.max(240,H*.34);
 rest.forEach((w,i)=>saet(w,(i%kol)*fb,H+Math.floor(i/kol)*fh,fb,fh));
 set.lay3=k;try{lsGem('rytme-set',JSON.stringify(set))}catch(e){}ws.scrollTop=0;ws.scrollLeft=0;try{skrivebordOpdat()}catch(e){}lay3UI();try{dockOpdat()}catch(e){}requestAnimationFrame(()=>{try{window.dispatchEvent(new Event('resize'))}catch(e){}});if(!stille)msg('Layout: '+(LAY3.find(x=>x[0]===k)||[0,k])[1]+'. '+(rest.length?'De øvrige '+rest.length+' vinduer ligger som små fliser længere nede; rul ned for at se dem.':''))}
function lay3UI(){document.querySelectorAll('#lay3 [data-lay3]').forEach(b=>{const on=b.dataset.lay3===set.lay3;b.classList.toggle('on',on);b.setAttribute('aria-pressed',on)});const s=$('lay3-mine');if(!s)return;const pl=layPladser(),v=s.value;s.innerHTML='<option value="">Mine ▾</option>'+pl.map((x,i)=>'<option value="'+i+'">'+(i+1)+' · '+(x?layEsc(x.navn||'uden navn'):'tom')+'</option>').join('');if(v)s.value=v}
setTimeout(function(){/* venter, til topbaren er bygget (det sker længere nede i programmet) */const tbm=$('tb')&&$('tb').querySelector('.tbm');if(!tbm)return;const d=document.createElement('div');d.id='lay3';d.className='lay3';d.setAttribute('role','group');d.setAttribute('aria-label','Layouts');
 d.innerHTML=LAY3.map(([k,n,t])=>'<button class="ghost" data-lay3="'+k+'" title="'+t+'">'+n+'</button>').join('')+'<select id="lay3-mine" title="Dine egne gemte layouts (pladserne 1 til 6). Vælg et for at bruge det." aria-label="Mine layouts"></select><button class="ghost" id="lay3-gem" title="Gem vinduernes placering nu. Er et af dine layouts valgt i Mine, gemmes der; ellers i den første tomme plads.">💾 Gem</button><button class="ghost laas" id="laas-knap" aria-pressed="false" title="Lås alle vinduers plads og størrelse på én gang. Tryk igen for at låse op.">🔓 Lås vinduer</button><button class="ghost" id="bred-knap" aria-pressed="false" title="Gør skrivebordet dobbelt så bredt, så store vinduer kan stå side om side. Rul vandret med Shift + musehjul.">↔ Bredt skrivebord</button>';
 const ref=$('kp-knap');if(ref&&ref.nextSibling)tbm.insertBefore(d,ref.nextSibling);else tbm.appendChild(d);
 d.addEventListener('click',e=>{const b=e.target.closest('[data-lay3]');if(b)lay3Anvend(b.dataset.lay3)});
 $('lay3-mine').addEventListener('change',e=>{const i=e.target.value;if(i==='')return;const x=layPladser()[+i];if(!x){msg('Plads '+(+i+1)+' er tom. Indret vinduerne og tryk 💾 Gem.');return}layBrug(x.data);set.lay3='';lay3UI();e.target.value=i;msg('Dit layout '+(x.navn||'')+' er i brug.')});
 $('lay3-gem').addEventListener('click',()=>{const a=layPladser(),s=$('lay3-mine');let i=s.value===''?a.findIndex(x=>!x):+s.value;if(i<0)i=0;const n=(a[i]&&a[i].navn)||'Mit layout '+(i+1);a[i]={navn:n,data:layNu()};layPladserGem(a);try{layBygListe()}catch(x){}lay3UI();$('lay3-mine').value=String(i);msg('💾 Layoutet er gemt i plads '+(i+1)+' ('+n+'). Omdøb det under ☰ Mere → Layouts.')});
 lay3UI();setTimeout(()=>{if(!set.lay3Init){set.lay3Init=1;lay3Anvend('overblik',true)}},400)},0);
/* oprydning: Radial Mesh fravælger med Esc */
document.addEventListener('keydown',e=>{if(e.key!=='Escape'||typeof meshSel==='undefined'||meshSel<0)return;const w=$('w5');if(!w||w.hidden||(w.classList.contains('scene-member')&&!w.classList.contains('scene-aktiv')))return;meshSel=-1;try{meshUI()}catch(x){}msg('Forbindelsen er fravalgt.')});
