/* ========== v8.4: GAIN-STAKKEN VISES OG KORT OVER FORBINDELSERNE ==========
   1) Ved hver forbindelse står den styrke, der faktisk bruges (gain-stakken, fagudtryk: gain staging): forbindelsens gain × Samlet styrke (master) × Afsnits-dynamik (show-vægt; kun når Show er slået til og en analyseret fil spiller). Har Adaptiv tærskel flyttet tærsklen, står den tærskel, der bruges. Det, AT noget påvirker, ses altid; detaljerne foldes ud med et klik (fagudtryk: progressive disclosure).
   2) Kort over forbindelserne: et Mermaid-kort (fagudtryk) af alle forbindelser lige nu, i fuld skærm med zoom, træk, kopiér kode og gem som PNG eller SVG. Tegneværktøjet hentes fra internettet første gang (mermaid 11.17.2); uden internet vises koden til at kopiere. */
const stakTal=x=>{const r=Math.round(x*100)/100;return String(r).replace('.',',')};
function stakFor(m,i){const kl=/^klods\d+$/.test(m.effect),tt=typeof now==='function'?now():0,gain=+m.gain||0,master=+gmaster;
 const showFindes=!!(SHOW&&SHOW.til&&m.rolle),showVirker=showFindes&&!live&&(playing||offset>0),vs=showVirker?Rytme.showVaegt(SHOW,m.rolle,tt):1;
 const lag=[['Forbindelsens gain',gain,true,'den du selv sætter']];
 lag.push(['Samlet styrke (vores navn; master)',master,master!==1,'gælder alle forbindelser; skydes i Radial Mesh']);
 if(showFindes)lag.push(['Afsnits-dynamik (vores navn; show-vægt)',vs,showVirker&&vs!==1,showVirker?'skruer op og ned efter vers, omkvæd og drop':'virker, når en analyseret fil spiller']);
 const styrke=lag.reduce((a,l)=>a*l[1],1),thrAuto=(set.tilpas&&TIL&&TIL.eff&&TIL.eff[i]!=null&&!TIL_SLAG.includes(m.band)&&BANDS.some(b=>b[0]===m.band))?TIL.eff[i]:null;
 return{lag,styrke,thr:thrAuto!=null?thrAuto:+m.thr,thrAuto,paavirket:lag.slice(1).filter(l=>l[2]).length}}
/* ---- kort over forbindelserne ---- */
const MVK={zoom:1,tal:true,nr:0,kode:''};
function mvkKode(){const ren=t=>String(t==null?'':t).replace(/["<>#|]/g,' ').replace(/\s+/g,' ').trim(),kort=n=>n.length>34?n.slice(0,33)+'…':n,fam=k=>k.startsWith('ana:')?'Analyse':k.startsWith('hnd:')?'Hændelser':k.startsWith('lk:')?'Fjernet (Lydkort)':k.startsWith('pad:')?'Fjernet (Morph Pad)':'Lydtræk';
 const L=['flowchart LR','  %% Claude MV v8.4 · dine forbindelser lige nu ('+maps.length+')'];if(!maps.length){L.push('  A["Ingen forbindelser endnu"]');return L.join('\n')}
 const kil=[...new Set(maps.map(m=>m.band))],kid={};kil.forEach((k,i)=>kid[k]='k'+i);
 L.push('  subgraph KILDER["Kilder · '+kil.length+'"]','    direction TB');kil.forEach(k=>L.push('    '+kid[k]+'(["'+kort(ren(bandNavn(k)))+'<br/>'+fam(k)+'"])'));L.push('  end');
 const mal=[...new Set(maps.map(m=>m.effect))],mid={},grp={};mal.forEach((e,i)=>{mid[e]='m'+i;let g='Globale effekter',n=ren(effName(e));if(e.startsWith('obj:')){const p=e.split(':'),o=fase2.objekter.find(x=>x.id===p[1]);g='Figur: '+ren(o?o.navn:p[1]);n=ren((PROPS[p[3]]||[p[3]])[0])}else if(/^klods\d+$/.test(e))g='Klodser';else if(e.startsWith('lyd:'))g='Lyd';(grp[g]=grp[g]||[]).push([e,n])});
 L.push('  subgraph MAAL["Mål · '+mal.length+'"]','    direction TB');Object.keys(grp).forEach((g,gi)=>{L.push('    subgraph G'+gi+'["'+g+'"]','      direction TB');grp[g].forEach(([e,n])=>L.push('      '+mid[e]+'["'+kort(n)+'"]'));L.push('    end')});L.push('  end');
 const fra=[];maps.forEach((m,i)=>{const S=stakFor(m,i),lab=['tærskel '+stakTal(S.thr),'styrke '+stakTal(S.styrke),Math.round(+m.att||0)+'/'+Math.round(+m.rel||0)+' ms'];if(m.hold)lab.push('hold');if(m.inv)lab.push('vendt');if(m.port)lab.push('port');if(m.off)lab.push('slået fra');
  const t=lab.join(' · ');L.push('  '+kid[m.band]+(m.off?(MVK.tal?' -. "'+t+'" .-> ':' -.-> '):(MVK.tal?' -- "'+t+'" --> ':' --> '))+mid[m.effect]);if(m.off)fra.push(i)});
 L.push('  classDef kilde fill:#0f2f3d,stroke:#59d2ff,color:#e8f8ff','  classDef maal fill:#2e2a0e,stroke:#ffd54a,color:#fff8dc','  class '+kil.map(k=>kid[k]).join(',')+' kilde','  class '+mal.map(e=>mid[e]).join(',')+' maal');return L.join('\n')}
function mvkHent(){return new Promise((ok,nej)=>{if(window.mermaid)return ok();const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/mermaid@11.17.2/dist/mermaid.min.js';sc.onload=()=>window.mermaid?ok():nej();sc.onerror=()=>nej();document.head.appendChild(sc)})}
function mvkZoom(){const s=$('mvk-ud').querySelector('svg');if(!s)return;const vb=s.viewBox&&s.viewBox.baseVal;if(!vb||!vb.width)return;s.removeAttribute('width');s.removeAttribute('height');s.style.maxWidth='none';s.style.width=Math.round(vb.width*MVK.zoom)+'px';s.style.height=Math.round(vb.height*MVK.zoom)+'px';$('mvk-z').textContent=Math.round(MVK.zoom*100)+' %'}
function mvkTilpas(){const s=$('mvk-ud').querySelector('svg');if(!s)return;const vb=s.viewBox.baseVal,f=$('mvk-flade');MVK.zoom=Math.max(.15,Math.min(1,(f.clientWidth-40)/vb.width));mvkZoom();f.scrollTop=0;f.scrollLeft=0}/* fylder bredden; høje kort rulles lodret, så teksten kan læses */
async function mvkTegn(){MVK.kode=mvkKode();$('mvk-txt').value=MVK.kode;$('mvk-info').textContent=maps.length+' forbindelser · '+new Set(maps.map(m=>m.band)).size+' kilder · '+new Set(maps.map(m=>m.effect)).size+' mål';
 try{await mvkHent()}catch(e){$('mvk-ud').innerHTML='<p class="mvk-tom">Tegneværktøjet (Mermaid) kunne ikke hentes; det kræver internet første gang. Koden står nedenfor: kopiér den med 📋 og sæt den ind i Mapping-kort-editoren.</p>';$('mvk-txt').hidden=false;return}
 try{mermaid.initialize({startOnLoad:false,securityLevel:'strict',theme:'dark',fontFamily:'system-ui,sans-serif',flowchart:{htmlLabels:false,curve:'basis',nodeSpacing:26,rankSpacing:90},themeVariables:{background:'#070b1c',primaryColor:'#151e42',primaryTextColor:'#e8ecff',lineColor:'#9aa6d6',clusterBkg:'#0e1530',clusterBorder:'#26315f',edgeLabelBackground:'#0e1530'}});
  const{svg}=await mermaid.render('mvkSvg'+(++MVK.nr),MVK.kode);$('mvk-ud').innerHTML=svg;$('mvk-txt').hidden=true;mvkTilpas()}
 catch(e){$('mvk-ud').innerHTML='<p class="mvk-tom">Kortet kunne ikke tegnes ('+String(e&&e.message||e).slice(0,120)+'). Koden står nedenfor.</p>';$('mvk-txt').hidden=false;document.querySelectorAll('body > [id^="dmvkSvg"]').forEach(n=>n.remove())}}
function mvkAaben(){$('mvk').hidden=false;mvkTegn();$('mvk-luk').focus()}
function mvkLuk(){$('mvk').hidden=true}
function mvkHentFil(navn,data,type){const a=document.createElement('a'),u=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));a.href=u;a.download=navn;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function mvkSvgTekst(){const s=$('mvk-ud').querySelector('svg');if(!s)return null;const c=s.cloneNode(true);c.setAttribute('xmlns','http://www.w3.org/2000/svg');c.style.width=s.viewBox.baseVal.width+'px';c.style.height=s.viewBox.baseVal.height+'px';return'<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(c)}
$('mvk-luk').onclick=mvkLuk;$('mvk-zind').onclick=()=>{MVK.zoom=Math.min(4,MVK.zoom*1.2);mvkZoom()};$('mvk-zud').onclick=()=>{MVK.zoom=Math.max(.1,MVK.zoom/1.2);mvkZoom()};$('mvk-tilpas').onclick=mvkTilpas;
