/* ========== v8.5: LÅS VINDUER ==========
   🔓/🔒 i topbaren låser alle vinduers plads og størrelse på én gang (de kan ikke trækkes eller gøres større/mindre). Layout-knapperne virker stadig, fordi man selv vælger dem. Valget huskes.
   Skrivebordet (arbejdsfladen) er altid mindst dobbelt så langt som det synlige. ↔ Bredt skrivebord gør det dobbelt så bredt; layoutene bruger så hele bredden, så store vinduer kan stå side om side, og man ruller vandret. Valget huskes. */
function skrivebordOpdat(){const ws=$('ws');if(!ws)return;let p=$('ws-plads');if(!p){p=document.createElement('div');p.id='ws-plads';p.setAttribute('aria-hidden','true');ws.prepend(p)}p.style.width=Math.round(ws.clientWidth*(set.bredt?2:1))+'px';p.style.height=Math.round(ws.clientHeight*2)+'px'}
function laasUI(){const l=!!set.laast,b=!!set.bredt;document.body.classList.toggle('laast',l);const k=$('laas-knap');if(k){k.textContent=l?'🔒 Vinduer låst':'🔓 Lås vinduer';k.classList.toggle('on',l);k.setAttribute('aria-pressed',l)}const q=$('bred-knap');if(q){q.classList.toggle('on',b);q.setAttribute('aria-pressed',b);q.textContent=b?'↔ Bredt skrivebord: til':'↔ Bredt skrivebord'}skrivebordOpdat()}
