const PICK=['storrelse','piglaengde','tykkelse','indre','rotation','rotY','rotX','drej','farveH','glod','skala','kontur','alpha'];
let armed=null;
function ensureSwing(o,li,p){const e=o.lag[li].egenskaber[p],d=PROPS[p],f=SWING[p];if(!f||e.fra!==e.til)return;const cl=v=>Math.max(d[1],Math.min(d[2],Math.round(v/d[3])*d[3]));let v=cl(f(e.fra));if(v===e.fra)v=e.fra>(d[1]+d[2])/2?d[1]:d[2];e.til=+v.toFixed(3)}
function ensureSwingT(tid){const[,oid,li,p]=tid.split(':'),o=fase2.objekter.find(x=>x.id===oid);if(o)ensureSwing(o,+li,p)}
function pickProp(oid){const o=fase2.objekter.find(x=>x.id===oid);if(!o)return null;const ps=propsFor(o.lag[0].form);for(const p of PICK)if(ps.includes(p)&&!maps.some(m=>m.effect===tidOf(o,0,p)))return tidOf(o,0,p);return tidOf(o,0,ps[0])}
function bindProp(o,li,p,band,stille){const tid=tidOf(o,li,p);Regler.samlet(()=>{Regler.sletHvor(m=>m.effect===tid);if(band){Regler.tilfoej(mk(band,tid,.3,1,20,200));ensureSwing(o,li,p)}});if(!stille){formUI();persistObj()}}
function bindArmed(band){if(!armed)return;const[,oid,li,p]=armed.split(':'),o=fase2.objekter.find(x=>x.id===oid);armed=null;if(!o)return;bindProp(o,+li,p,band);msg('Koblet '+PROPS[p][0]+' til '+bandNavn(band)+'. Justér tærskel m.m. i Node-editoren, EQ eller Radial Mesh.')}
function autoKobl(){const{o,l,li}=cur();let n=0;Regler.samlet(()=>uiProps(l.form).forEach(p=>{const b=AUTOKOBL[p];if(b&&!maps.some(m=>m.effect===tidOf(o,li,p))){bindProp(o,li,p,b,true);n++}}));formUI();persistObj();msg(n?'Auto-kobl: '+n+' egenskaber koblet, med et synligt udsving. Finjustér i Node-editoren, EQ eller Radial Mesh.':'Auto-kobl: alle oplagte egenskaber er allerede koblet.')}
function addMorgenstjerne(udenRegler){let o=fase2.objekter.find(x=>x.id==='ms');if(!o){if(fase2.objekter.length>=MAXO){msg('Højst '+MAXO+' figurer.');return}o=nyMorgenstjerne();fase2.objekter.push(o)}
 if(!udenRegler)Regler.samlet(()=>[['hmid','piglaengde',.3],['bas','storrelse',.2],['flux','drej',.2],['kick','skala',.3],['vokal','svaev',.2],['vokal','loeft',.2]].forEach(([b,p,thr])=>{const tid='obj:ms:0:'+p;if(!maps.some(m=>m.effect===tid)){const e=o.lag[0].egenskaber[p];e.fra=MS_FRA[p];e.til=MS_TIL[p];Regler.tilfoej(mk(b,tid,thr,1,20,250))}}));
 selO=fase2.objekter.indexOf(o);selL=0;struktur();msg(udenRegler?'Morgenstjerne lagt på scenen uden regler. Regel-sættet Morgenstjerne ligger i Biblioteket → Figurer → Morgenstjerne.':'Morgenstjerne tilføjet som figur med forbindelser')}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&armed){armed=null;formUI();msg('Afbrudt')}});
$('mtarget').onchange=e=>{const m=maps[meshSel];if(!m)return;m.effect=e.target.value;renderMaps();save()};
syncTargets();syncHandles();try{formUI()}catch(e){console.error('Form-editoren kunne ikke tegnes ved opstart:',e);setTimeout(()=>{try{formUI()}catch(x){}},0)}sceneUI();lydUI();/* Levende objekter (livscyklus): afkrydsning, skydere, placering ved fødsel og knappen Kobl fødsel */
$('fctl').addEventListener('change',e=>{const t=e.target,{o}=cur();
 if(t.id==='fliv'){const L=livKopi(o.liv);L.til=t.checked;o.liv=L;if(!L.til)Regler.sletHvor(m=>m.effect==='liv:'+o.id);struktur();renderMaps();msg(L.til?'Levende: figuren er nu en model. Kobl Fødsel til et lydtræk, så fødes en levende kopi ved hvert anslag.':'Levende er slået fra: figuren er et almindeligt, fast figur igen.');return}
 if(t.dataset.lvp){const L=livKopi(o.liv);L.plac[t.dataset.lvp]=t.value;o.liv=L;persistObj();return}
 if(t.dataset.lvf!==undefined){const L=livKopi(o.liv);L.fodtAf=t.value;o.liv=L;persistObj();formUI();msg('Fødes af: '+(LIV_M.find(x=>x[0]===t.value)||[0,t.value])[1]+'.');return} if(t.dataset.lvo){const L=livKopi(o.liv),k=t.dataset.lvo;let v=String(t.value||'');if(k==='tast'){v=v.slice(0,1).toLowerCase();if(!v){t.value=L.fodtOpt.tast;return}if(/[a-pæ]/.test(v)&&!/[bcimnqrvxz]/.test(v))msg('Bemærk: '+v.toUpperCase()+' er også en klavertast, så den spiller også en tone, når klaveret er slået til.')}L.fodtOpt[k]=v;o.liv=L;persistObj();return}
 if(t.dataset.lvt!==undefined){const L=livKopi(o.liv);L.toneFarve=t.checked;o.liv=L;persistObj()}});
$('fctl').addEventListener('input',e=>{const t=e.target,k=t.dataset.lv;if(!k)return;const{o}=cur(),L=livKopi(o.liv),v=+t.value;
 if(k==='dx'||k==='dy'||k==='dz')L.drift[k[1]]=v;else L[k]=v;o.liv=livKopi(L);const b=$('fctl').querySelector('[data-lvv="'+k+'"]');if(b)b.textContent=(k==='dx'||k==='dy'||k==='dz')?o.liv.drift[k[1]]:o.liv[k];persistObj()});
$('fctl').addEventListener('click',e=>{if(e.target.id!=='flivkobl')return;const{o}=cur(),b=$('flivband').value,tid='liv:'+o.id;if(!o.liv||!o.liv.til)return;
 Regler.samlet(()=>{Regler.sletHvor(m=>m.effect===tid);Regler.tilfoej(Object.assign(mk(b,tid,.3,1,10,150),{gap:150}))});formUI();msg('Koblet Fødsel til '+bandNavn(b)+'. Justér tærskel m.m. i Node-editoren, EQ eller Radial Mesh.')});
opsByg();opsOpdat();kvalByg();kvalOpdat();
